 fields:[{id:'rev',label:'إجمالي المبيعات الشهرية',type:'number',ph:'مثال: 80000'},{id:'cogs',label:'تكلفة البضاعة المباعة',type:'number',ph:'مثال: 45000'},{id:'rent',label:'الإيجار',type:'number',def:0},{id:'sal',label:'الرواتب والعمالة',type:'number',def:0},{id:'mkt',label:'التسويق والإعلانات',type:'number',def:0},{id:'oth',label:'مصاريف أخرى (كهرباء، إنترنت، نقل...)',type:'number',def:0},{id:'tax',label:'ضرائب % على الربح (اختياري)',type:'number',def:0}],ex:{rev:80000,cogs:45000,rent:6000,sal:12000,mkt:3000,oth:2000,tax:10},
 run:function(v){N(v,'rev','cogs');var gp=v.rev-v.cogs;var exp=(v.rent||0)+(v.sal||0)+(v.mkt||0)+(v.oth||0);var op=gp-exp;var tx=op>0?op*(v.tax||0)/100:0;var net=op-tx;return {rows:[['مجمل الربح',m(gp)],['إجمالي المصاريف التشغيلية',m(exp)],['الربح التشغيلي',m(op)],['الضريبة',m(tx)],[net>=0?'صافي الربح':'صافي الخسارة',m(Math.abs(net)),1],['هامش صافي الربح',v.rev?f(net/v.rev*100,2)+'%':'—'],['صافي الربح السنوي (تقدير)',m(net*12)]],note:'تقدير مبني على أرقامك. لا يغني عن محاسب قانوني.'}},
