/* ===== doc builders ===== */
function csvEsc(s){s=String(s===null||s===undefined?'':s);return /[",\n\r]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function dl(name,text,type){U().download(new Blob(['\ufeff'+text],{type:type||'text/csv;charset=utf-8'}),name)}
function docBuilder(cfg){
 return function(root){
  var key='doc-'+cfg.kind;var S=EDDA.LS.get(key,null)||cfg.init();
  var cols=cfg.cols;
  root.innerHTML='<div class="noprint">'+(cfg.head?'<div class="fgrid" id="hd"></div>':'')+'<h3 style="margin:16px 0 6px;font-size:1rem">'+cfg.itemsTitle+'</h3><div class="tblwrap"><table class="dtab"><thead><tr>'+cols.map(function(c){return '<th>'+c.label+'</th>'}).join('')+'<th></th></tr></thead><tbody id="rows"></tbody></table></div><div class="acts"><button class="btn sm" id="addr" type="button">+ إضافة سطر</button><button class="btn sm" id="clr" type="button">مسح الكل</button></div>'+(cfg.totals?'<div class="fgrid" id="ft" style="margin-top:14px"></div>':'')+'<div class="acts"><button class="btn pri" id="prt" type="button">طباعة / حفظ PDF</button><button class="btn" id="csv" type="button">تنزيل CSV</button>'+(cfg.xls?'<button class="btn" id="xls" type="button">تنزيل Excel</button>':'')+(cfg.json?'<button class="btn" id="jsn" type="button">تنزيل JSON</button>':'')+'<button class="btn" id="cpy" type="button">نسخ كنص</button></div><p class="rnote">تُحفظ بياناتك تلقائيًا على جهازك فقط. لحفظ PDF اختر «حفظ كـ PDF» من نافذة الطباعة.</p><h3 style="margin:16px 0 6px;font-size:1rem">المعاينة</h3></div><div class="paper" id="paper"></div>';
  var q=function(s){return root.querySelector(s)};
  function inp(label,id,val,type){return '<div class="fld"><label for="h-'+id+'">'+label+'</label><input type="'+(type||'text')+'" id="h-'+id+'" value="'+U().esc(val||'')+'"></div>'}
  if(cfg.head){q('#hd').innerHTML=cfg.head.map(function(h){return inp(h[1],h[0],S[h[0]],h[2])}).join('');cfg.head.forEach(function(h){q('#h-'+h[0]).addEventListener('input',function(e){S[h[0]]=e.target.value;sv()})})}
  if(cfg.totals){q('#ft').innerHTML=cfg.totals.map(function(h){return inp(h[1],h[0],S[h[0]],'text')}).join('');cfg.totals.forEach(function(h){var e=q('#h-'+h[0]);e.setAttribute('dir','ltr');e.setAttribute('inputmode','decimal');e.addEventListener('input',function(){S[h[0]]=e.value;sv()})})}
  function num(x){x=parseFloat(String(x).replace(/,/g,''));return isNaN(x)?0:x}
  function calcT(){var sub=0;S.rows.forEach(function(r){if(cfg.lineTotal)sub+=cfg.lineTotal(r,num)});return sub}
  function drawRows(){var tb=q('#rows');tb.innerHTML='';S.rows.forEach(function(r,i){var tr=document.createElement('tr');cols.forEach(function(c){var td=document.createElement('td');var e=document.createElement('input');e.type='text';e.value=r[c.id]||'';e.setAttribute('aria-label',c.label);if(c.num){e.setAttribute('inputmode','decimal');e.dir='ltr'}e.style.width=c.w||'100%';e.addEventListener('input',function(){r[c.id]=e.value;sv()});td.appendChild(e);tr.appendChild(td)});var td=document.createElement('td');var x=document.createElement('button');x.type='button';x.className='btn sm';x.textContent='حذف';x.onclick=function(){S.rows.splice(i,1);if(!S.rows.length)S.rows.push({});drawRows();sv()};td.appendChild(x);tr.appendChild(td);tb.appendChild(tr)})}
  function plain(){return cfg.text(S,num,calcT)}
  function paper(){q('#paper').innerHTML=cfg.paper(S,num,calcT,U().esc)}
  function sv(){EDDA.LS.set(key,S);paper()}
  q('#addr').onclick=function(){S.rows.push({});drawRows();sv()};
  q('#clr').onclick=function(){if(confirm('هل تريد مسح كل البيانات؟')){S=cfg.init();EDDA.LS.set(key,S);root.innerHTML='';cfg.fn(root)}};
  q('#prt').onclick=function(){window.print()};
  q('#csv').onclick=function(){dl(cfg.kind+'.csv',cfg.csv(S,num,calcT))};
  if(cfg.xls)q('#xls').onclick=function(){var rows=cfg.csvRows(S,num,calcT);var h='<html xmlns:x="urn:schemas-microsoft-com:office:excel"><head><meta charset="utf-8"></head><body dir="rtl"><table border="1">'+rows.map(function(r,i){return '<tr>'+r.map(function(c){return (i===0?'<th>':'<td>')+U().esc(c)+(i===0?'</th>':'</td>')}).join('')+'</tr>'}).join('')+'</table></body></html>';dl(cfg.kind+'.xls','<?xml version="1.0" encoding="UTF-8"?>'+h,'application/vnd.ms-excel')};
  if(cfg.json)q('#jsn').onclick=function(){dl(cfg.kind+'.json',JSON.stringify(S.rows.filter(function(r){return Object.keys(r).some(function(k){return r[k]})}),null,2),'application/json')};
  q('#cpy').onclick=function(){U().copy(plain())};
  drawRows();paper();
 };
}
function mkInvoice(kind,title,numLabel){
 var cfg={kind:kind,itemsTitle:'البنود',
 head:[['seller','اسم البائع / الشركة'],['client','اسم العميل'],['no',numLabel],['date','التاريخ','date'],['cur','العملة (نص يظهر بجانب الأرقام)'],['note','ملاحظات / شروط']],
 totals:[['tax','ضريبة %'],['disc','خصم %'],['ship','شحن / رسوم إضافية']],
 cols:[{id:'name',label:'الوصف',w:'100%'},{id:'qty',label:'الكمية',num:1,w:'80px'},{id:'price',label:'سعر الوحدة',num:1,w:'110px'}],
 init:function(){return {seller:'',client:'',no:'001',date:new Date().toISOString().slice(0,10),cur:'جنيه',note:'',tax:'0',disc:'0',ship:'0',rows:[{name:'',qty:'1',price:''},{}]}},
 lineTotal:function(r,n){return n(r.qty)*n(r.price)}};
 function sums(S,n,ct){var sub=ct();var d=sub*n(S.disc)/100;var a=sub-d;var t=a*n(S.tax)/100;return {sub:sub,d:d,a:a,t:t,s:n(S.ship),tot:a+t+n(S.ship)}}
 function R(x){return U().money(x)}
 cfg.paper=function(S,n,ct,e){var s=sums(S,n,ct);var rows=S.rows.filter(function(r){return r.name||r.price});return '<h2>'+title+(S.no?' رقم '+e(S.no):'')+'</h2><p style="margin:2px 0">التاريخ: '+e(S.date||'')+'</p><p style="margin:2px 0"><b>من:</b> '+e(S.seller||'—')+'</p><p style="margin:2px 0 12px"><b>إلى:</b> '+e(S.client||'—')+'</p><table><thead><tr><th>#</th><th>الوصف</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>'+(rows.length?rows.map(function(r,i){return '<tr><td>'+(i+1)+'</td><td>'+e(r.name||'')+'</td><td>'+e(r.qty||'')+'</td><td>'+R(n(r.price))+'</td><td>'+R(n(r.qty)*n(r.price))+'</td></tr>'}).join(''):'<tr><td colspan="5" style="text-align:center">أضف بنودًا لتظهر هنا</td></tr>')+'</tbody></table><table style="width:50%;margin:12px 0 0 auto"><tr><td>المجموع</td><td>'+R(s.sub)+'</td></tr>'+(s.d?'<tr><td>الخصم ('+e(S.disc)+'%)</td><td>-'+R(s.d)+'</td></tr>':'')+(s.t?'<tr><td>الضريبة ('+e(S.tax)+'%)</td><td>'+R(s.t)+'</td></tr>':'')+(s.s?'<tr><td>شحن / رسوم</td><td>'+R(s.s)+'</td></tr>':'')+'<tr><th>الإجمالي ('+e(S.cur||'')+')</th><th>'+R(s.tot)+'</th></tr></table>'+(S.note?'<p style="margin-top:14px"><b>ملاحظات:</b> '+e(S.note)+'</p>':'')};
 cfg.csvRows=function(S,n,ct){var s=sums(S,n,ct);var r=[['الوصف','الكمية','سعر الوحدة','الإجمالي']];S.rows.filter(function(x){return x.name||x.price}).forEach(function(x){r.push([x.name||'',n(x.qty),n(x.price),n(x.qty)*n(x.price)])});r.push(['','','المجموع',s.sub],['','','الخصم',s.d],['','','الضريبة',s.t],['','','الشحن',s.s],['','','الإجمالي',s.tot]);return r};
 cfg.csv=function(S,n,ct){return cfg.csvRows(S,n,ct).map(function(r){return r.map(csvEsc).join(',')}).join('\r\n')};
 cfg.text=function(S,n,ct){var s=sums(S,n,ct);return title+(S.no?' رقم '+S.no:'')+'\nالتاريخ: '+S.date+'\nمن: '+S.seller+'\nإلى: '+S.client+'\n\n'+S.rows.filter(function(x){return x.name||x.price}).map(function(x,i){return (i+1)+'. '+x.name+' × '+x.qty+' = '+R(n(x.qty)*n(x.price))}).join('\n')+'\n\nالإجمالي: '+R(s.tot)+' '+S.cur};
 cfg.xls=true;cfg.json=false;cfg.fn=docBuilder(cfg);return cfg.fn;
}
function docTool(id,title,desc,kw,mount,extra){T({id:id,cat:'biz',title:title,desc:desc,kw:kw,mount:mount,how:extra.how,example:extra.example,about:extra.about,when:extra.when,faqs:extra.faqs,related:extra.related})}
docTool('invoice-generator','إنشاء فاتورة بسيطة','أنشئ فاتورة بسيطة بالبنود والخصم والضريبة والإجمالي، واطبعها أو احفظها PDF أو نزّلها CSV وExcel.','إنشاء فاتورة invoice فاتورة مبيعات',mkInvoice('invoice','فاتورة','رقم الفاتورة'),{how:['أدخل بيانات البائع والعميل ورقم الفاتورة.','أضف البنود بالكمية والسعر، ثم الخصم والضريبة.','اطبع الفاتورة أو احفظها PDF أو نزّلها CSV أو Excel.'],example:'أضف بندين: «تصميم شعار» بسعر 1500 و«استضافة سنة» بسعر 600 بضريبة 14%، وستظهر الفاتورة جاهزة للطباعة.',about:'أداة لإنشاء فاتورة مبسطة بصيغة منظمة: بيانات الطرفين، جدول بنود، خصم وضريبة وإجمالي. تُحسب الأرقام تلقائيًا وتُحفظ بياناتك على جهازك فقط. هذه فاتورة بسيطة وليست فاتورة ضريبية إلكترونية معتمدة.',when:'للفريلانسر وأصحاب المشاريع الصغيرة الذين يحتاجون فاتورة سريعة لعميل دون برنامج محاسبة.',faqs:[['هل هي فاتورة رسمية معتمدة؟','لا، هي قالب مبسط. في بعض البلدان يلزم نظام فوترة إلكترونية معتمد، فالتزم بمتطلبات بلدك.'],['كيف أحفظها PDF؟','اضغط «طباعة / حفظ PDF» ثم اختر «حفظ كـ PDF» كوجهة الطباعة.'],['هل تُرفع بيانات عملائي؟','لا، تبقى على جهازك.']],related:['quotation-generator','order-total-calculator','price-list-generator']});
docTool('quotation-generator','إنشاء عرض سعر','أنشئ عرض سعر احترافي ببنود وخصم وضريبة وملاحظات الصلاحية، واطبعه أو احفظه PDF.','عرض سعر quotation quote',mkInvoice('quotation','عرض سعر','رقم العرض'),{how:['أدخل بيانات شركتك والعميل ورقم العرض.','أضف الخدمات أو المنتجات بالكمية والسعر.','اكتب مدة صلاحية العرض في الملاحظات ثم اطبعه أو احفظه PDF.'],example:'أضف «تطوير موقع» بسعر 8000 و«صيانة 3 أشهر» بسعر 1500 واكتب في الملاحظات: «العرض ساري 14 يومًا».',about:'عرض السعر مستند يوضح للعميل ما ستقدمه وتكلفته قبل الاتفاق. تنظم الأداة البنود والخصم والضريبة وتحسب الإجمالي، وتتيح كتابة شروط العرض ومدة صلاحيته.',when:'عند الرد على استفسار عميل بسعر رسمي، أو التقديم لمناقصة صغيرة أو مشروع.',faqs:[['ما الفرق بين الفاتورة وعرض السعر؟','عرض السعر قبل الاتفاق وغير ملزم عادة، والفاتورة بعد تقديم الخدمة أو البيع.'],['هل أكتب مدة صلاحية؟','نعم، اكتبها في الملاحظات لتجنب تغير الأسعار.'],['كيف أحفظه PDF؟','من نافذة الطباعة اختر الحفظ كـ PDF.']],related:['invoice-generator','price-list-generator']});
function mkTable(kind,title,cols,withTotals){
 var cfg={kind:kind,itemsTitle:'الجدول',head:kind==='price-list'?[['title','عنوان القائمة'],['cur','العملة'],['note','ملاحظة أسفل القائمة']]:[['title','عنوان الجدول (اختياري)']],cols:cols,
 init:function(){var o={title:'',cur:'جنيه',note:'',rows:[{},{},{}]};return o},lineTotal:null};
 function R(r){return cols.map(function(c){return r[c.id]||''})}
 cfg.paper=function(S,n,ct,e){var rows=S.rows.filter(function(r){return cols.some(function(c){return r[c.id]})});return '<h2>'+e(S.title||title)+'</h2>'+(S.cur&&kind==='price-list'?'<p style="margin:2px 0 8px">الأسعار بالـ '+e(S.cur)+'</p>':'')+'<table><thead><tr>'+cols.map(function(c){return '<th>'+e(c.label)+'</th>'}).join('')+'</tr></thead><tbody>'+(rows.length?rows.map(function(r){return '<tr>'+R(r).map(function(x){return '<td>'+e(x)+'</td>'}).join('')+'</tr>'}).join(''):'<tr><td colspan="'+cols.length+'" style="text-align:center">أضف صفوفًا لتظهر هنا</td></tr>')+'</tbody></table>'+(S.note?'<p style="margin-top:12px">'+e(S.note)+'</p>':'')};
 cfg.csvRows=function(S){var r=[cols.map(function(c){return c.label})];S.rows.filter(function(x){return cols.some(function(c){return x[c.id]})}).forEach(function(x){r.push(R(x))});return r};
 cfg.csv=function(S,n,ct){return cfg.csvRows(S).map(function(r){return r.map(csvEsc).join(',')}).join('\r\n')};
 cfg.text=function(S){return cfg.csvRows(S).map(function(r){return r.join(' | ')}).join('\n')};
 cfg.xls=true;cfg.json=true;cfg.fn=docBuilder(cfg);return cfg.fn;
}
docTool('price-list-generator','إنشاء قائمة أسعار','أنشئ قائمة أسعار منظمة لمنتجاتك أو خدماتك، واطبعها أو احفظها PDF أو صدّرها CSV وExcel.','قائمة أسعار price list منيو',mkTable('price-list','قائمة الأسعار',[{id:'name',label:'المنتج أو الخدمة'},{id:'unit',label:'الوحدة',w:'110px'},{id:'price',label:'السعر',num:1,w:'110px'},{id:'note',label:'ملاحظة'}]),{how:['اكتب عنوان القائمة والعملة.','أضف المنتجات بأسعارها ووحداتها.','اطبع القائمة أو احفظها PDF أو صدّرها.'],example:'أضف خدمات كالتالي: «قص شعر - للفرد - 100» و«صبغة - للفرد - 350» ثم اطبع القائمة وعلقها في المحل.',about:'قائمة الأسعار تعرض منتجاتك وأسعارها بشكل واضح لعملائك. تتيح لك الأداة تجهيز قائمة مرتبة قابلة للطباعة والمشاركة، وتصديرها كملف CSV أو Excel أو JSON.',when:'لمحل أو مطعم أو مقدم خدمة يريد عرض الأسعار على العملاء بشكل مرتب.',faqs:[['كيف أرسلها لعميل؟','احفظها PDF من نافذة الطباعة ثم أرسل الملف.'],['هل أستطيع فتحها في Excel؟','نعم، نزّل ملف Excel أو CSV.'],['هل تتزامن بين أجهزتي؟','لا، تُحفظ على جهازك فقط.']],related:['product-table-exporter','invoice-generator','quotation-generator']});
docTool('product-table-exporter','إنشاء جدول منتجات قابل للتصدير','أنشئ جدول منتجات (اسم، كود، كمية، سعر، فئة) وصدّره بصيغة CSV أو Excel أو JSON أو اطبعه.','جدول منتجات تصدير excel csv مخزون',mkTable('products','جدول المنتجات',[{id:'name',label:'اسم المنتج'},{id:'sku',label:'الكود',w:'100px'},{id:'cat',label:'الفئة',w:'110px'},{id:'qty',label:'الكمية',num:1,w:'80px'},{id:'price',label:'السعر',num:1,w:'100px'}]),{how:['أضف منتجاتك سطرًا بسطر مع الكود والكمية والسعر.','راجع المعاينة أسفل الجدول.','نزّل الجدول بصيغة CSV أو Excel أو JSON أو اطبعه.'],example:'أضف منتجات متجرك ثم صدّر ملف CSV لرفعه إلى منصة متجر إلكتروني أو فتحه في Excel.',about:'أداة لتجهيز بيانات المنتجات في جدول منظم قابل للتصدير بصيغ شائعة: CSV لبرامج الجداول والمتاجر، وExcel للفتح المباشر، وJSON للمطورين. يُحفظ ما تكتبه على جهازك فقط.',when:'لتجهيز قائمة مخزون أو بيانات لرفعها على متجر إلكتروني أو لمشاركتها مع مورد.',faqs:[['هل يظهر العربي صحيحًا في Excel؟','نعم، تُحفظ الملفات بترميز UTF-8 مع علامة BOM ليظهر العربي سليمًا.'],['هل أستطيع استيراد ملف؟','لا، الأداة للإنشاء والتصدير فقط.'],['ما حجم الجدول المناسب؟','مئات الصفوف مناسبة للاستخدام العادي.']],related:['price-list-generator','invoice-generator']});
